                    path.append(came_from[tuple(map(tuple, current_state))][1])
                    current_state = came_from[tuple(map(tuple, current_state))][0]
                path.reverse()
                return path

            possible_moves = self.get_possible_moves(current_state)
            for move in possible_moves:
                new_state = self.move(current_state.copy(), move)
                if tuple(map(tuple, new_state)) not in came_from:
                    came_from[tuple(map(tuple, new_state))] = (current_state, move)
                    open_list.append(new_state)

        return None
